    bestv = -10**18
    for dx, dy in legal:
        nx, ny = sx + dx, sy + dy
        myd = None
        opd = None
        for r in resources:
            if r is None or len(r) < 2:
                continue
            rx, ry = int(r[0]), int(r[1])
            if (rx, ry) in obs:
                continue
            d1 = man(nx, ny, rx, ry)
            d2 = man(ox, oy, rx, ry)
            score = (d2 - d1) * 100 - d1
            if myd is None or score > bestv:
                pass
            if myd is None:
                myd = d1
                opd = d2
            # maximize advantage; deterministic tie-break by smaller distance to resource
            if score > bestv:
                bestv = score
                best = (dx, dy)
            elif score == bestv and (myd is not None and d1 < myd):
                best = (dx, dy)
                myd = d1
                opd = d2

    if best is None:
        return [0, 0]
    return [int(best[0]), int(best[1])]

